import Foundation
import FoundationModels

/// Carries a tool-produced image from the off-main-actor tool call back to the main-actor
/// `ChatEngine`.
///
/// `Tool.call` runs on the concurrent executor (the protocol requirement is `@concurrent`) and
/// a `Tool` must be `Sendable`, so the generated bytes can't be written straight onto the
/// main-context `ChatMessage`. The tool stashes them here; after `session.respond` returns to
/// the main actor, the engine drains this collector and attaches the image to the assistant
/// message. An `actor` keeps the hand-off race-free under Swift 6 strict concurrency.
///
/// Only the most recent image is kept: if the model calls the tool more than once in a single
/// turn, the last picture wins (a `ChatMessage` holds one image).
actor GeneratedImageCollector {
    private var latest: Data?

    func store(_ data: Data) {
        latest = data
    }

    /// Returns the image produced during the current turn (if any) and clears it, so the next
    /// turn starts empty.
    func take() -> Data? {
        defer { latest = nil }
        return latest
    }

    /// Discards any leftover image before a turn begins — defensive against a prior turn that
    /// generated an image but failed before it was drained.
    func reset() {
        latest = nil
    }
}

/// A FoundationModels `Tool` that wraps `ImageGenerator`, registered on the live
/// `LanguageModelSession`. Letting the model call this directly means it decides when to
/// generate, writes a genuine natural-language reply about the image it made, and handles
/// follow-ups like "make it bigger" natively — no out-of-model classifier or acknowledgment
/// reframing.
///
/// `call` runs off the main actor, so the generated bytes are handed to the engine through the
/// `Sendable` `GeneratedImageCollector` rather than touched onto the SwiftData context here.
struct ImageGenerationTool: Tool {
    let name = "generateImage"
    let description = """
        Generates a picture, drawing, illustration, logo, or other visual on-device from a text \
        description and shows it to the user. Call this whenever the user wants an image created \
        — including when they accept an image you offered to make. For a follow-up like "make it \
        bigger" or "more colorful", call again with an updated description of the image already \
        created. Do not call it for ordinary questions or chat.
        """

    @Generable
    struct Arguments {
        @Guide(description: "A vivid, self-contained visual description of the image to create, capturing the subject and any style the user asked for.")
        var prompt: String
    }

    let collector: GeneratedImageCollector

    func call(arguments: Arguments) async throws -> String {
        // Throwing here propagates to `session.respond` as a `ToolCallError`; the engine unwraps
        // it into a friendly message. No image is stored, so the turn records no false success.
        let imageData = try await ImageGenerator.generate(prompt: arguments.prompt)
        await collector.store(imageData)
        return "Generated the image and displayed it to the user."
    }
}
